public final class METRebateCombinedContract
{
    private TAMRebateFromDate fromDate;
    private TAMRebateToDate toDate;
    private TransDate transDate;
    private boolean runInParallel = true;
    private boolean processRebate = false;
    private boolean processWriteOff = false;
    private boolean processProvision = false;
    private boolean postRebate = false;
    private boolean postProvision = false;
    private boolean postWriteOff = false;

    private str packedQuery;
    private METAutoSetDate metAutoSetDate;
}

Method.Source:
public static METRebateCombinedContract construct()
{
    return new METRebateCombinedContract();
}

[DataMember, SysOperationDisplayOrder('1'), SysOperationGroupMember('Period')]
public TAMRebateFromDate parmFromDate(TAMRebateFromDate _fromDate = fromDate)
{
    fromDate = _fromDate;

    return fromDate;
}

