[DataMember, SysOperationDisplayOrder('3'), SysOperationLabel("@MET:METRebateCombinedBatchThread"), SysOperationGroupMember('RunMode')]
public boolean parmRunInParallel(boolean _runInParallel = runInParallel)
{
    // Yes = parallel create-trans (one task per work unit, single-threaded posting).
    // No  = single-threaded sequential run over the whole selection.
    runInParallel = _runInParallel;

    return runInParallel;
}

